const budget = 0.001; // 0.1% for a 99.9% SLO
const reqPerHour = 100;

function rate(failures, hours) {
  const total = reqPerHour * hours;
  return { total, errorRate: failures / total };
}

const oneHour = rate(1, 1);
const sevenDay = rate(1, 24 * 7);
console.log(`1h window:  ${oneHour.total} req, errRate=${(oneHour.errorRate * 100).toFixed(3)}% -> ${oneHour.errorRate > budget ? 'BREACH' : 'ok'}`);
console.log(`7d window:  ${sevenDay.total} req, errRate=${(sevenDay.errorRate * 100).toFixed(4)}% -> ${sevenDay.errorRate > budget ? 'BREACH' : 'ok'}`);

// burn = (budget_fraction * period_hours) / window_hours, 30-day period = 720h
const burn = (frac, period, window) => (frac * period) / window;
console.log(`14.4x page = ${burn(0.02, 720, 1)}`);
console.log(`6x page    = ${burn(0.05, 720, 6)}`);
console.log(`1x ticket  = ${burn(0.10, 720, 72)}`);
console.log(`28-day 14.4x becomes ${burn(0.02, 672, 1)}`);
